#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind {
    Bool,
    SignedInt,
    UnsignedInt,
    Float,
    Complex,
    Object,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct DType {
    kind: Kind,
    precedence: u8,
}

impl DType {
    // constructor for convenience
    fn new(kind: Kind, precedence: u8) -> Self {
        Self { kind, precedence }
    }
}

/// Task 1:
/// Given a non-empty collection of `DType`s, return a `DType`
/// from that collection that has the maximum precedence value.
fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // We can safely unwrap because input is non-empty
    *types.iter()
        .max_by_key(|dt| dt.precedence)
        .unwrap()
}

/// Task 2:
/// Given two collections representing array and scalar dtypes (either may be empty, 
/// but at least one is non-empty), determine the common dtype following:
/// - If only arrays: max precedence dtype in arrays
/// - If only scalars: max precedence dtype in scalars
/// - If both non-empty:
///     - get max from each
///     - if kinds equal, return array max
///     - else return scalar max
fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let array_max = array_types.iter().max_by_key(|dt| dt.precedence);
    let scalar_max = scalar_types.iter().max_by_key(|dt| dt.precedence);

    match (array_max, scalar_max) {
        (None, None) => None, // both empty - problem states at least one non-empty, so this is safe fallback
        (Some(&a_max), None) => Some(a_max), // only array non-empty
        (None, Some(&s_max)) => Some(s_max), // only scalar non-empty
        (Some(&a_max), Some(&s_max)) => {
            if a_max.kind == s_max.kind {
                Some(a_max)
            } else {
                Some(s_max)
            }
        }
    }
}

// -- Example usage/demo (not required by the problem, but illustrative) --
#[cfg(test)]
mod tests {
    use super::*;

    fn dtype_bool() -> DType { DType::new(Kind::Bool, 0) }
    fn dtype_i8() -> DType { DType::new(Kind::SignedInt, 1) }
    fn dtype_i16() -> DType { DType::new(Kind::SignedInt, 2) }
    fn dtype_u8() -> DType { DType::new(Kind::UnsignedInt, 5) }
    fn dtype_f32() -> DType { DType::new(Kind::Float, 9) }
    fn dtype_f64() -> DType { DType::new(Kind::Float, 10) }
    fn dtype_complex128() -> DType { DType::new(Kind::Complex, 12) }
    fn dtype_object() -> DType { DType::new(Kind::Object, 13) }

    #[test]
    fn test_find_max_precedence_type() {
        let types = vec![dtype_bool(), dtype_i8(), dtype_u8(), dtype_f32()];
        let max_type = find_max_precedence_type(types);
        assert_eq!(max_type, dtype_f32());
    }

    #[test]
    fn test_find_common_type_only_array() {
        let array_types = vec![dtype_i8(), dtype_i16(), dtype_u8()];
        let scalar_types = vec![];
        let common = find_common_type(array_types, scalar_types);
        assert_eq!(common, Some(dtype_u8()));
    }

    #[test]
    fn test_find_common_type_only_scalar() {
        let array_types = vec![];
        let scalar_types = vec![dtype_i8(), dtype_i16()];
        let common = find_common_type(array_types, scalar_types);
        assert_eq!(common, Some(dtype_i16()));
    }

    #[test]
    fn test_find_common_type_both_same_kind() {
        // array max: f64 (kind Float, precedence 10)
        // scalar max: f32 (kind Float, precedence 9)
        // kinds same -> return array max = f64
        let array_types = vec![dtype_f32(), dtype_f64()];
        let scalar_types = vec![dtype_f32()];
        let common = find_common_type(array_types, scalar_types);
        assert_eq!(common, Some(dtype_f64()));
    }

    #[test]
    fn test_find_common_type_both_different_kind() {
        // array max: i16 (SignedInt, 2)
        // scalar max: complex128 (Complex, 12)
        // kinds differ -> return scalar max = complex128
        let array_types = vec![dtype_i8(), dtype_i16()];
        let scalar_types = vec![dtype_complex128()];
        let common = find_common_type(array_types, scalar_types);
        assert_eq!(common, Some(dtype_complex128()));
    }
}